      "code": "import subprocess
import sys
import json

def test_r1_target_json_literal():
    result = subprocess.run(
        [sys.executable, '-m', 'glom', 'a', '{"a": 1}'],
        capture_output=True, text=True
    )
    assert result.returncode == 0
    assert json.loads(result.stdout) == 1

def test_r1_target_python_literal():
    result = subprocess.run(
        [sys.executable, '-m', 'glom', '--target-format', 'python', 'a', "{'a': 1}"],
        capture_output=True, text=True
    )
    assert result.returncode == 0
    assert json.loads(result.stdout) == 1

def test_r1_spec_python_full():
    result = subprocess.run(
        [sys.executable, '-m', 'glom', '--spec-format', 'python-full', 'sorted', '[3,1,2]'],
        capture_output=True, text=True
    )
    assert result.returncode == 0
    assert json.loads(result.stdout) == [1, 2, 3]

def test_r1_spec_python_full_lambda():
    result = subprocess.run(
        [sys.executable, '-m', 'glom', '--spec-format', 'python-full', 'lambda x: x["a"]', '{"a": 1}'],
        capture_output=True, text=True
    )
    assert result.returncode == 0
    assert json.loads(result.stdout) == 1"
